pub fn runtime_boxed_abi(symbol: &str, arity: usize) -> Option<&'static RuntimeBoxedAbi> {
    let index = RUNTIME_BOXED_ABIS
        .binary_search_by_key(&symbol, |abi| abi.symbol)
        .ok()?;
    let abi = &RUNTIME_BOXED_ABIS[index];
    (abi.arity == arity).then_some(abi)
}
